class MinStack:
    def __init__(self):
        self.st = []                        # pairs: (value, smallest so far)

    def push(self, x):
        low = x
        if self.st:
            low = min(x, self.st[-1][1])    # compare with the note below
        self.st.append((x, low))

    def pop(self):
        self.st.pop()                       # the note leaves with its value

    def top(self):
        return self.st[-1][0]

    def getMin(self):
        return self.st[-1][1]

