import java.util.ArrayDeque;
import java.util.Deque;

class MinStack {
    // each entry is {value, smallest so far}
    private final Deque<int[]> st = new ArrayDeque<>();

    public void push(int x) {
        int low = st.isEmpty() ? x : Math.min(x, st.peek()[1]);
        st.push(new int[] {x, low});
    }

    public void pop() {
        st.pop();
    }

    public int top() {
        return st.peek()[0];
    }

    public int getMin() {
        return st.peek()[1];
    }
}

