#include <algorithm>
#include <stack>
#include <utility>

class MinStack {
    // each entry is (value, smallest so far)
    std::stack<std::pair<int, int>> st;

public:
    void push(int x) {
        int low = st.empty() ? x : std::min(x, st.top().second);
        st.push({x, low});
    }

    void pop() { st.pop(); }

    int top() { return st.top().first; }

    int getMin() { return st.top().second; }
};

