class MinStack {
  constructor() {
    this.st = [];                      // pairs: [value, smallest so far]
  }

  push(x) {
    const below = this.st[this.st.length - 1];
    const low = below ? Math.min(x, below[1]) : x;
    this.st.push([x, low]);
  }

  pop() {
    this.st.pop();
  }

  top() {
    return this.st[this.st.length - 1][0];
  }

  getMin() {
    return this.st[this.st.length - 1][1];
  }
}

